{
  "name": "spawn-policy",
  "version": "0.1.0",
  "description": "Enforces the role-to-model map and synchronous review dispatch on agent.spawn in autonomous sessions, and logs every rewrite",
  "author": {
    "name": "alienfast"
  },
  "userConfig": {
    "enforce": {
      "type": "string",
      "title": "Enforce",
      "description": "auto rewrites only in autonomous sessions (the auto skill has run, or the spawn's permission mode is auto) and logs elsewhere; always rewrites everywhere; never only logs.",
      "options": [
        "auto",
        "always",
        "never"
      ],
      "default": "auto"
    },
    "developer_model": {
      "type": "string",
      "title": "developer model",
      "description": "Model alias or id every developer spawn runs on.",
      "default": "sonnet"
    },
    "verifier_model": {
      "type": "string",
      "title": "quality-verifier model",
      "description": "Model alias or id every quality-verifier spawn runs on.",
      "default": "sonnet"
    },
    "reviewer_model": {
      "type": "string",
      "title": "quality-reviewer model",
      "description": "Model alias or id every quality-reviewer spawn runs on.",
      "default": "opus"
    },
    "sync_review_dispatch": {
      "type": "boolean",
      "title": "Synchronous review dispatch",
      "description": "Rewrite run_in_background to false on main-loop spawns of quality-reviewer, quality-verifier and developer.",
      "default": true
    },
    "ledger": {
      "type": "boolean",
      "title": "Write ledger",
      "description": "Append one JSONL row per decision to tmp/spawn-policy-<session>.jsonl under the session root.",
      "default": true
    }
  }
}
